function ResultModal({value,registrations,saving,error,onClose,onSubmit}:{value:any;registrations:any[];saving:boolean;error?:string;onClose:()=>void;onSubmit:(v:any)=>Promise<void>}){
 const [v,setV]=useState<any>(value??{});
 const selected=registrations.find(r=>r.id===v.registrationId);
 const classes=[...(selected?.classes??[])].sort((a:any,b:any)=>(a.class?.direction?.sortOrder??999)-(b.class?.direction?.sortOrder??999)||(a.class?.sortOrder??999)-(b.class?.sortOrder??999)||String(a.class?.name??'').localeCompare(String(b.class?.name??''),'ru'));
 return <Modal title={v.id?'Исправление результата':'Новый результат'} onClose={onClose}>
  {error&&<div className="form-error modal-form-error"><AlertTriangle size={16}/><span>{error}</span></div>}
  <form className="form modal-form" onSubmit={e=>{e.preventDefault();void onSubmit(v)}}>
   {!v.id&&<>
    <label>Регистрация<select value={v.registrationId??''} onChange={e=>setV({...v,registrationId:e.target.value,registrationClassId:''})} required><option value="">Выберите участника</option>{registrations.map(r=><option key={r.id} value={r.id}>№{r.participantNumber} · {[r.participant?.lastName,r.participant?.firstName].filter(Boolean).join(' ')} · {displayCarName(r.car)}</option>)}</select></label>
    <label>Класс регистрации<select value={v.registrationClassId??''} onChange={e=>setV({...v,registrationClassId:e.target.value})} required><option value="">Выберите класс</option>{classes.map((x:any)=><option key={x.id} value={x.id}>{x.class?.direction?.name?x.class.direction.name+' · ':''}{x.class?.name} · {enumLabel(x.class?.unit)}</option>)}</select></label>
   </>}
   <label>Результат<input type="number" step="0.001" min="0" value={v.value??''} onChange={e=>setV({...v,value:e.target.value})} required/></label>
   <label>Место<input type="number" min="1" max="999" value={v.place??''} onChange={e=>setV({...v,place:e.target.value})}/></label>
   <label>Комментарий<textarea rows={4} value={v.notes??''} onChange={e=>setV({...v,notes:e.target.value})}/></label>
   <button className="primary-button" disabled={saving||(!v.id&&(!v.registrationId||!v.registrationClassId))}>{saving?'Сохраняем…':'Сохранить результат'}</button>
  </form>
 </Modal>
}
